// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    // fuzz params: an address 'from' and a uint v and uint len to build varying _tos lengths
    function testFuzz_property(address from, uint256 v, uint256 len) public {
        // keep domain reasonable: len > 0 and not too large to avoid OOG in fuzz
        uint256 tosLen = bound(len, 1, 8);

        // deploy a helper that will revert when called, to distinguish behavior
        Reverter reverter = new Reverter();
        // build recipients array: include at least one address that will cause the callee to revert
        address[] memory tos = new address[](tosLen);
        // fill with the reverter address and some arbitrary EOAs derived from fuzzed 'from'
        for (uint i = 0; i < tosLen; i++) {
            // mix addresses so some entries may be harmless EOAs
            if (i == (tosLen - 1)) {
                tos[i] = address(reverter);
            } else {
                // create pseudo-random but deterministic addresses from inputs
                tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, v, i)))));
            }
        }

        bool ok;
        // call transfer; reference C should revert because one callee (reverter) will revert and C requires success
        try c.transfer(from, address(reverter), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: reference C always reverts (so ok==false) whenever any callee invocation reverts.
        // We assert that the call did NOT succeed (ok == false). The mutant removing require(_s) will
        // allow ok == true for some inputs (i.e., it will return true even though the callee reverted),
        // causing this test to fail on the mutant for some fuzzed inputs.
        assertTrue(!ok);
    }
}

contract Reverter {
    // any call to this contract should revert to simulate a failing callee
    fallback() external payable {
        revert("revert in callee");
    }
    receive() external payable {
        revert("revert in callee");
    }
}
